import os, sys, subprocess, base64, io, tarfile
from pathlib import Path
os.environ['CUDA_VISIBLE_DEVICES']=''
root=Path('/kaggle/working/code'); root.mkdir(parents=True,exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(''))) as archive: archive.extractall(root)
subprocess.check_call([sys.executable,'-m','pip','install','-q','ultralytics==8.4.0','pycocotools','pandas'])
weights=list(Path('/kaggle/input').rglob('checkpoints/best.pt'))
if len(weights)!=1: raise RuntimeError(f'Expected one exp002 checkpoint, got {weights}')
annotations=next(Path('/kaggle/input').rglob('MAGFiLO_1.0_Annotations_kaggle2026_train.json'))
images=next(Path('/kaggle/input').rglob('train_images'))
os.environ['PYTHONPATH']=str(root)
subprocess.check_call([sys.executable,'-u','-m','experiments.exp_033_inference.src.sweep','--weights',str(weights[0]),'--annotations',str(annotations),'--images',str(images),'--output','/kaggle/working/results','--variants','identity','gamma_0.8','gamma_1.2'],cwd=root)
